from solution import min_penalty

def test_min_penalty_empty():
    assert min_penalty([]) == 0

def test_min_penalty_single_building():
    assert min_penalty([10]) == 0

def test_min_penalty_two_buildings_different_heights():
    assert min_penalty([5, 10]) == 0

def test_min_penalty_two_buildings_same_height():
    assert min_penalty([10, 10]) == 0

def test_min_penalty_multiple_buildings():
    assert min_penalty([5, 1, 6, 8]) == 0

def test_min_penalty_penalty_case():
    assert min_penalty([1, 2, 1, 2, 1]) == 0
